function detectLang(){
  if (window.__pickedLang && LANGS.includes(window.__pickedLang)) return window.__pickedLang;
  try {
    const saved = localStorage.getItem("potw-lang");
    if (LANGS.includes(saved)) return saved;
  } catch (e) {}
  const nav = (navigator.language || "en").toLowerCase();
  if (nav.startsWith("ja")) return "ja";
  if (nav.startsWith("tr")) return "tr";
  if (nav.startsWith("es")) return "es";
  if (nav.startsWith("fr")) return "fr";
  if (nav.startsWith("de")) return "de";
  if (nav.startsWith("it")) return "it";
  if (nav.startsWith("ko")) return "ko";
  if (nav.startsWith("ru")) return "ru";
  if (nav.startsWith("el")) return "el";
  return "en";
}

function trAblative(name){
  var clean = String(name || "").trim();
  if (!clean) return clean;
  var parts = clean.split(/[\s-]+/);
  var token = parts[parts.length - 1] || clean;
  var front = {e:1,i:1,"ö":1,"ü":1};
  var voiceless = {"ç":1,f:1,h:1,k:1,p:1,s:1,"ş":1,t:1};
  var buffer = {"Adaları":1,"Sahili":1,"Cumhuriyeti":1};
  var letter = {A:"a",B:"e",C:"e",D:"e",E:"e",F:"e",G:"e",H:"e",I:"ı",J:"e",K:"e",L:"e",M:"e",N:"e",O:"o",P:"e",R:"e",S:"e",T:"e",U:"u",V:"e",Y:"e",Z:"e"};
  var harmony = "a";
  if (/^[A-Z]{2,6}$/.test(token)) {
    var lv = letter[token.slice(-1)] || "e";
    harmony = front[lv] ? "e" : "a";
  } else {
    for (var i = 0; i < token.length; i++) {
      var ch = token.charAt(i);
      var lower = ch === "I" ? "ı" : ch === "İ" ? "i" : ch.toLocaleLowerCase("tr");
      if ("aıou".indexOf(lower) >= 0) harmony = "a";
      else if ("eiöü".indexOf(lower) >= 0) harmony = "e";
    }
  }
  var last = token.slice(-1).toLocaleLowerCase("tr");
  var endsVowel = "aeıioöuü".indexOf(last) >= 0;
  var consonant = (endsVowel || !voiceless[last]) ? "d" : "t";
  var n = (endsVowel && buffer[token]) ? "n" : "";
  return clean + "’" + n + consonant + harmony + "n";
}
