function koCount(value){
  return value
    .replace(/(\d+(?:\.\d+)?)\s*billion\b/g, (_, n) => (Math.round(parseFloat(n) * 100) / 10) + "억")
    .replace(/(\d+(?:\.\d+)?)\s*million\b/g, (_, n) => (Math.round(parseFloat(n) * 1000) / 10) + "만")
    .replace(/\s*\((\d{4})\s*est\.\)/g, "（$1년 추산）")
    .replace(/\best\./g, "추산");
}
function euroFigures(value, billion, million, est){
  const grouped = value.replace(/(\d),(?=\d{3}(?:\D|$))/g, "$1.");
  return grouped
    .replace(/(\d+)\.(\d+)\s*billion\b/g, "$1,$2 " + billion)
    .replace(/(\d+)\.(\d+)\s*million\b/g, "$1,$2 " + million)
    .replace(/\bbillion\b/g, billion)
    .replace(/\bmillion\b/g, million)
    .replace(/\best\./g, est);
}
function figureText(value){
  if (LANG === "ja") return jaCount(value);
  if (LANG === "ko") return koCount(value);
  if (LANG === "es") return esFigures(value);
  if (LANG === "fr") return frFigures(value);
  if (LANG === "de") return deFigures(value);
  if (LANG === "it") return euroFigures(value, "miliardi", "milioni", "stima");
  if (LANG === "ru") return euroFigures(value, "млрд", "млн", "оценка");
  if (LANG === "el") return euroFigures(value, "δισ.", "εκατ.", "εκτίμηση");
  return trFigures(value);
}
function localizeFact(value){
  if (!value || LANG === "en") return value || "";
  let out = figureText(value);
  const table = WORDS[LANG] || {};
  const keys = Object.keys(table).sort((a,b) => b.length - a.length);
  for (const k of keys) out = out.split(k).join(LANG === "es" ? esCap(table[k]) : table[k]);
  return out;
}
function setLang(next){
  LANG = next;
  try { localStorage.setItem("potw-lang", next); } catch (e) {}
  if (typeof window.onLangChange === "function") window.onLangChange(next);
  else if (typeof applyI18n === "function") applyI18n();
}
